INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der PDCA-Zyklus nur für große Projekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Verbesserungen nutzbar"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Plan-Schritts?', 3, '[{"text": "Strategieentwicklung", "correct": true, "because": "Legt Ziele und Maßnahmen fest"}, {"text": "Sofortige Umsetzung", "correct": false, "because": "Erst im Do-Schritt"}, {"text": "Manuelle Kontrolle", "correct": false, "because": "Check-Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zum PDCA-Zyklus?', 5, '[{"text": "Planen", "correct": true, "because": "Definiert Ziele"}, {"text": "Überprüfen", "correct": true, "because": "Bewertet Ergebnisse"}, {"text": "Entwerfen", "correct": false, "because": "Kein PDCA-Schritt"}, {"text": "Archivieren", "correct": false, "because": "Nicht Teil des Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Do-Schritt testet Maßnahmen. b) Act ersetzt die Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) optimiert, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Anwendung von PDCA?', 4, '[{"text": "Ergebnismessung", "correct": false, "because": "Kern des Check-Schritts"}, {"text": "Kontinuierliche Verbesserung", "correct": false, "because": "Ziel von Act"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für PDCA"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PDCA einmalig angewendet wird?', 2, '[{"text": "Nein", "correct": true, "because": "Zyklisch für stetige Verbesserung"}, {"text": "Ja", "correct": false, "because": "Wiederholend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist im Check-Schritt entscheidend?', 3, '[{"text": "Datenanalyse", "correct": true, "because": "Bewertet Maßnahmen"}, {"text": "Sofortige Umsetzung", "correct": false, "because": "Do-Schritt"}, {"text": "Manuelle Planung", "correct": false, "because": "Plan-Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der PDCA-Zyklus?', 5, '[{"text": "Systematische Verbesserung", "correct": true, "because": "Strukturiert Prozesse"}, {"text": "Fehlerreduktion", "correct": true, "because": "Überprüfung optimiert"}, {"text": "Einmalige Lösung", "correct": false, "because": "Zyklisch, nicht einmalig"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher vereinfachend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PDCA fördert kontinuierliche Verbesserung. b) Es ist nur für Produktion. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist universell einsetzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für PDCA?', 4, '[{"text": "Ziele", "correct": false, "because": "Plan-Schritt benötigt sie"}, {"text": "Daten", "correct": false, "because": "Check-Schritt benötigt sie"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für PDCA"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Act-Schritt der letzte?', 2, '[{"text": "Nein", "correct": true, "because": "Führt zurück zu Plan"}, {"text": "Ja", "correct": false, "because": "Zyklisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte verbessern Prozesse direkt?', 4, '[{"text": "Do", "correct": true, "because": "Testet Maßnahmen"}, {"text": "Act", "correct": true, "because": "Setzt Optimierungen um"}, {"text": "Archivieren", "correct": false, "because": "Kein PDCA-Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PDCA immer langwierig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann schnell angewendet werden"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im Plan-Schritt?', 3, '[{"text": "Klare Ziele", "correct": true, "because": "Leiten Maßnahmen"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Do-Schritt"}, {"text": "Manuelle Tests", "correct": false, "because": "Check-Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Check bewertet Ergebnisse. b) PDCA ist nur für IT-Prozesse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen PDCA effektiv?', 5, '[{"text": "Iterative Anwendung", "correct": true, "because": "Fördert stetige Verbesserung"}, {"text": "Datenbasierte Entscheidungen", "correct": true, "because": "Sichern Objektivität"}, {"text": "Einmalige Anwendung", "correct": false, "because": "Widerspricht Zyklus"}, {"text": "Hohe Komplexität", "correct": false, "because": "Vereinfacht Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei PDCA unwichtig?', 3, '[{"text": "Dokumentation", "correct": false, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Messgrößen", "correct": false, "because": "Grundlage für Check"}, {"text": "Bildbearbeitung", "correct": true, "because": "Kein PDCA-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PDCA für einmalige Probleme geeignet?', 3, '[{"text": "Ja", "correct": true, "because": "Kann auch kurzfristig helfen"}, {"text": "Nein", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PDCA nur von Teams genutzt wird?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einzeln anwendbar"}, {"text": "Ja", "correct": false, "because": "Individuell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu PDCA?', 4, '[{"text": "Optimierung eines IT-Supports", "correct": true, "because": "Verbessert Prozesse systematisch"}, {"text": "Erstellung eines Logos", "correct": false, "because": "Kreative Aufgabe"}, {"text": "Hardwaremontage", "correct": false, "because": "Physikalische Aufgabe"}]');
